# First, load what we have so far to verify nothing was saved
import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    session_file = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')
    try:
        content = open(session_file).read().replace('\\n', '\n')
    except FileNotFoundError:
        return {}

    G = {}
    # Pattern: "Demo pair N input/output" or "Test input (WxH):"
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    m0 = re.search(pattern, content)
    if m0:
        txt_after = content[m0.end():]
        lines = txt_after.split('\n')[:int(m0.group(2))]
        grid_rows = []
        for line in lines:
            if line.strip() == '': continue
            row = [int(x) for x in line.strip().split()]
            grid_rows.append(row)
        G[m0.group(1)] = grid_rows
    return G

G = load_grids()
print("Loaded grids:", sorted(G.keys()))
if G:
    for k, v in G.items():
        print(f"\n{k}:")
        for row in v:
            print(row)

